package net.officefloor.hq.app.pool;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.crew.Crew;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's pot is the pot of each pool that is a member of none; a pool that is a member of another
 * has its cut in that pool as its pot. A read made as of a date (see {@link AsOf}) answers with the pools,
 * their members and the pot as they stood at the end of it. Each crew is a pool too, under its name, listed
 * among the pools by name: its lead and members at equal shares, the sheet's pot its pot.
 */
public class RespondWithPools {
    public void respond(@Val Sheet sheet, PoolRepository repository, CrewRepository crews, SettingsRepository settings,
            HttpServletRequest request, ObjectResponse<PoolsResponse> response) {
        LocalDate asOf = AsOf.of(request);
        List<PoolMember> members = new ArrayList<>(repository.members(sheet.id(), sheet.today(), asOf));
        members.addAll(repository.crewMembers(sheet.id(), sheet.today(), asOf));
        BigDecimal sheetPot = (asOf == null ? settings.find(sheet.id()) : settings.findAsOf(sheet.id(), asOf)).pot();
        List<Pool> pools = new ArrayList<>(repository.findAll(sheet.id(), asOf));
        Map<String, Long> crewIds = new HashMap<>();
        for (Crew c : crews.findAll(sheet.id(), asOf)) {
            crewIds.put(c.name(), c.id());
            pools.add(new Pool(c.id(), sheet.id(), c.name()));
        }
        pools.sort(Comparator.comparing(Pool::name));
        Map<String, List<PoolMember>> byPool = new HashMap<>();
        for (Pool p : pools) {
            byPool.put(p.name(), members.stream().filter(m -> m.pool().equals(p.name())).toList());
        }
        Map<String, BigDecimal> pots = new HashMap<>();
        response.send(new PoolsResponse(pools.stream()
                .map(p -> {
                    BigDecimal pot = pot(p.name(), members, byPool, sheetPot, pots);
                    Long crewId = crewIds.get(p.name());
                    return crewId == null ? PoolResponse.from(p, byPool.get(p.name()), pot)
                            : PoolResponse.ofCrew(p, crewId, byPool.get(p.name()), pot);
                })
                .toList()));
    }

    /** The pool's pot: the sheet's when it is a member of no pool, else its cut in the pool above (null for none). */
    private static BigDecimal pot(String pool, List<PoolMember> members, Map<String, List<PoolMember>> byPool,
            BigDecimal sheetPot, Map<String, BigDecimal> pots) {
        if (pots.containsKey(pool)) return pots.get(pool);
        BigDecimal pot = sheetPot;
        for (PoolMember m : members) {
            if (!pool.equals(m.memberPool())) continue;
            List<PoolMember> above = byPool.get(m.pool());
            List<BigDecimal> cuts = PoolResponse.cutsOf(above, pot(m.pool(), members, byPool, sheetPot, pots));
            pot = cuts == null ? null : cuts.get(above.indexOf(m));
            break;
        }
        pots.put(pool, pot);
        return pot;
    }
}
package net.officefloor.hq.app.pool;

/**
 * A pool member, as the screen reads it: the person's id ('' for a member pool) or the member pool's
 * name ('' for a person), the name, their share, whether they are retired, and their cut of the pool's
 * pot with two decimals ('' for none), its from- and to-dates ('' for open) and whether they
 * include the sheet's today.
 */
public record PoolMemberResponse(String personId, String memberPool, String name, String share, boolean retired,
        String cut, String from, String to, boolean active) {
    public static PoolMemberResponse from(PoolMember m, java.math.BigDecimal cut) {
        return new PoolMemberResponse(m.personId() == null ? "" : String.valueOf(m.personId()),
                m.memberPool() == null ? "" : m.memberPool(), m.name(), m.share().toPlainString(), m.retired(),
                cut == null ? "" : cut.toPlainString(), m.from() == null ? "" : m.from().toString(),
                m.to() == null ? "" : m.to().toString(), m.active());
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

/**
 * A pool, as the screen reads it: its members in the order added, the total of their shares (a retired
 * member's counting as given) and whether that total is exactly 100.00. Each member of a balanced pool
 * has a cut of the sheet's pot: the pot times their share divided by the shares of the members with a cut
 * added up, rounded half to even to two decimals (a retired member's, and a member held on the sheet's
 * today, 0.00), with the remainder, the pot minus the cuts added up, going to the member with the
 * smallest non-zero cut, the latest added on a tie (a member with no cut gets none; when no cut is
 * non-zero, to the last member with a cut and a share), so the cuts total exactly the pot (each is 0.00
 * when no member has a cut). A pool whose every member is retired has no cuts. A hold or a retirement changes neither the total nor whether the pool is balanced. An
 * unbalanced pool, or no pot, has no cuts. A member whose dates do not include the sheet's today is
 * left out entirely: not in the total, not in the balance, and no cut (not even 0.00). A pool that is a member of another has no pot of its own: its
 * pot is its cut in the pool above (none when that pool has no cuts). {@code added} orders the pools as they
 * were added (a larger one added later), a crew's after every pool. {@code crew} is whether it is a crew's
 * pool: its lead and members at equal shares, kept by the crew (no member is added to it as to a pool).
 */
public record PoolResponse(String name, List<PoolMemberResponse> members, String totalShare, boolean balanced,
        long added, boolean crew) {
    /** Added to a crew's id for its {@code added}, so the crews' pools come after every pool. */
    static final long CREW_ADDED = 1_000_000_000_000L;

    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    public static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot) {
        return from(pool, members, pot, pool.id(), false);
    }

    /** A crew's pool: named as the crew, {@code crewId} the crew's id. */
    public static PoolResponse ofCrew(Pool pool, long crewId, List<PoolMember> members, BigDecimal pot) {
        return from(pool, members, pot, CREW_ADDED + crewId, true);
    }

    private static PoolResponse from(Pool pool, List<PoolMember> members, BigDecimal pot, long added, boolean crew) {
        BigDecimal total = total(members);
        boolean balanced = total.compareTo(HUNDRED) == 0;
        List<BigDecimal> cuts = cutsOf(members, pot);
        List<PoolMemberResponse> shown = new ArrayList<>();
        for (int i = 0; i < members.size(); i++) {
            shown.add(PoolMemberResponse.from(members.get(i), cuts == null ? null : cuts.get(i)));
        }
        return new PoolResponse(pool.name(), shown, total.toPlainString(), balanced, added, crew);
    }

    /** The active members' shares added up, a retired member's counting as given. */
    static BigDecimal total(List<PoolMember> members) {
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (PoolMember m : members) if (m.active()) total = total.add(m.share());
        return total;
    }

    /**
     * Each member's cut of the pot, in the members' order; null when the pool is unbalanced, there is no pot,
     * or every member is retired.
     */
    static List<BigDecimal> cutsOf(List<PoolMember> members, BigDecimal pot) {
        boolean allRetired = members.stream().filter(PoolMember::active).allMatch(PoolMember::retired);
        return pot != null && !allRetired && total(members).compareTo(HUNDRED) == 0 ? cuts(members, pot) : null;
    }

    /** Whether the member has a cut: active, neither retired nor held on the sheet's today. */
    private static boolean hasCut(PoolMember m) {
        return m.active() && !m.retired() && !m.held();
    }

    private static List<BigDecimal> cuts(List<PoolMember> members, BigDecimal pot) {
        BigDecimal shares = BigDecimal.ZERO;
        for (PoolMember m : members) if (hasCut(m)) shares = shares.add(m.share());
        List<BigDecimal> cuts = new ArrayList<>();
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int smallest = -1;
        int lastShared = -1;
        for (int i = 0; i < members.size(); i++) {
            PoolMember m = members.get(i);
            if (!m.active()) {
                cuts.add(null);
                continue;
            }
            BigDecimal cut = !hasCut(m) || shares.signum() == 0 ? BigDecimal.ZERO.setScale(2)
                    : pot.multiply(m.share()).divide(shares, 2, RoundingMode.HALF_EVEN);
            cuts.add(cut);
            sum = sum.add(cut);
            if (!hasCut(m)) continue;
            if (m.share().signum() > 0) lastShared = i;
            if (cut.signum() != 0 && (smallest < 0 || cut.compareTo(cuts.get(smallest)) <= 0)) smallest = i;
        }
        int to = smallest >= 0 ? smallest : lastShared;
        if (to >= 0 && shares.signum() > 0) cuts.set(to, cuts.get(to).add(pot.subtract(sum)));
        return cuts;
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;

/** The pools on a sheet, by name. */
public record PoolsResponse(List<PoolResponse> pools) {
}
package net.officefloor.hq.app;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;

/**
 * The as-of date the signed-in user's screen reads the sheet at, named on each read in the
 * {@code X-As-Of} header (yyyy-MM-dd). While it is set, a read answers with the sheet as it stood at
 * the end of that date: every change made while the sheet's today was on or before it, and that
 * date standing in for the sheet's today. Changes never carry it.
 */
public final class AsOf {

    public static final String HEADER = "X-As-Of";

    private AsOf() {
    }

    /** The as-of date the request reads at, or null when it reads the sheet as it is now. */
    public static LocalDate of(HttpServletRequest request) {
        String raw = request == null ? null : request.getHeader(HEADER);
        if (raw == null || raw.isBlank()) return null;
        try {
            return LocalDate.parse(raw.trim());
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
