package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The pools store, kept per sheet. */
@Repository
public class PoolRepository {

    private final JdbcTemplate jdbc;

    public PoolRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's pools, by name. */
    public List<Pool> findAll(String sheetId) {
        return findAll(sheetId, null);
    }

    /** The sheet's pools, by name: as they stood at the end of {@code asOf} (null: now). */
    public List<Pool> findAll(String sheetId, LocalDate asOf) {
        return jdbc.query("SELECT id, sheet_id, name FROM pool WHERE sheet_id = ?"
                + " AND (CAST(? AS DATE) IS NULL OR added_on IS NULL OR added_on <= ?) ORDER BY name",
                (rs, n) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name")),
                sheetId, sqlDate(asOf), sqlDate(asOf));
    }

    /** The pool with this name on the sheet, or null when there is none. */
    public Pool find(String sheetId, String name) {
        List<Pool> found = jdbc.query("SELECT id, sheet_id, name FROM pool WHERE sheet_id = ? AND name = ?",
                (rs, n) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name")), sheetId, name);
        return found.isEmpty() ? null : found.get(0);
    }

    public Pool save(String sheetId, String name) {
        jdbc.update("INSERT INTO pool (sheet_id, name, added_on) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?))",
                sheetId, name, sheetId);
        return find(sheetId, name);
    }

    /**
     * The members of every pool on the sheet, each pool's in the order they were added: people and member pools,
     * a person held when one of their holds covers {@code today}, a member active when its dates include it.
     */
    public List<PoolMember> members(String sheetId, LocalDate today) {
        return members(sheetId, today, null);
    }

    /**
     * The members as they stood at the end of {@code asOf} (null: now): only those added, to pools added,
     * by then, and each person's retirement and holds as given by then.
     */
    public List<PoolMember> members(String sheetId, LocalDate today, LocalDate asOf) {
        Date on = sqlDate(asOf);
        String added = "(CAST(? AS DATE) IS NULL OR %1$s.added_on IS NULL OR %1$s.added_on <= ?)";
        return jdbc.query("SELECT pl.name AS pool, m.person_id, mp.name AS member_pool, COALESCE(p.name, mp.name) AS name,"
                + " m.share, m.from_date, m.to_date, CASE WHEN CAST(? AS DATE) IS NULL THEN p.retired_from ELSE"
                + " (SELECT r.from_date FROM person_retirement r WHERE r.person_id = m.person_id AND r.set_on <= ?"
                + " ORDER BY r.id DESC LIMIT 1) END AS retired_from,"
                + " EXISTS (SELECT 1 FROM person_hold h WHERE h.person_id = m.person_id"
                + " AND h.from_date <= ? AND (h.to_date IS NULL OR h.to_date >= ?)"
                + " AND " + added.formatted("h").replace("added_on", "made_on") + ") AS held FROM pool_member m"
                + " JOIN pool pl ON pl.id = m.pool_id LEFT JOIN person p ON p.id = m.person_id"
                + " LEFT JOIN pool mp ON mp.id = m.member_pool_id"
                + " WHERE pl.sheet_id = ? AND " + added.formatted("m") + " AND " + added.formatted("pl")
                + " AND (m.person_id IS NULL OR " + added.formatted("p") + ")"
                + " AND (m.member_pool_id IS NULL OR " + added.formatted("mp") + ")"
                + " ORDER BY pl.name, m.id",
                (rs, n) -> {
                    long personId = rs.getLong("person_id");
                    Long id = rs.wasNull() ? null : personId;
                    Date from = rs.getDate("from_date");
                    Date to = rs.getDate("to_date");
                    LocalDate fromDate = from == null ? null : from.toLocalDate();
                    LocalDate toDate = to == null ? null : to.toLocalDate();
                    return new PoolMember(sheetId, rs.getString("pool"), id,
                            rs.getString("member_pool"), rs.getString("name"), rs.getBigDecimal("share"),
                            rs.getDate("retired_from") != null, rs.getBoolean("held"), fromDate, toDate,
                            PoolMember.covers(fromDate, toDate, today));
                }, on, on, Date.valueOf(today), Date.valueOf(today), on, on, sheetId, on, on, on, on, on, on, on, on);
    }

    /**
     * The members of every crew on the sheet as a pool's (see {@link #crewShares}): each crew's lead first, then its
     * members in the order added, as they stood at the end of {@code asOf} (null: now); a person held when one of
     * their holds covers {@code today}. A crew's members have no dates, so are always active.
     */
    public List<PoolMember> crewMembers(String sheetId, LocalDate today, LocalDate asOf) {
        Date on = sqlDate(asOf);
        String added = "(CAST(? AS DATE) IS NULL OR %1$s.added_on IS NULL OR %1$s.added_on <= ?)";
        String flags = " CASE WHEN CAST(? AS DATE) IS NULL THEN p.retired_from ELSE"
                + " (SELECT r.from_date FROM person_retirement r WHERE r.person_id = p.id AND r.set_on <= ?"
                + " ORDER BY r.id DESC LIMIT 1) END AS retired_from,"
                + " EXISTS (SELECT 1 FROM person_hold h WHERE h.person_id = p.id"
                + " AND h.from_date <= ? AND (h.to_date IS NULL OR h.to_date >= ?)"
                + " AND " + added.formatted("h").replace("added_on", "made_on") + ") AS held";
        Date day = Date.valueOf(today);
        List<Object[]> rows = jdbc.query("SELECT pool, ord, person_id, name, retired_from, held FROM ("
                + "SELECT c.name AS pool, 0 AS ord, p.id AS person_id, p.name AS name," + flags
                + " FROM crew c JOIN person p ON p.id = c.lead_id WHERE c.sheet_id = ? AND " + added.formatted("c")
                + " UNION ALL SELECT c.name AS pool, m.id AS ord, p.id AS person_id, p.name AS name," + flags
                + " FROM crew_member m JOIN crew c ON c.id = m.crew_id JOIN person p ON p.id = m.person_id"
                + " WHERE c.sheet_id = ? AND " + added.formatted("c") + " AND " + added.formatted("m")
                + ") x ORDER BY pool, ord",
                (rs, n) -> new Object[] { rs.getString("pool"), rs.getLong("person_id"), rs.getString("name"),
                        rs.getDate("retired_from") != null, rs.getBoolean("held") },
                on, on, day, day, on, on, sheetId, on, on,
                on, on, day, day, on, on, sheetId, on, on, on, on);
        Map<String, List<Object[]>> byCrew = new LinkedHashMap<>();
        for (Object[] row : rows) byCrew.computeIfAbsent((String) row[0], k -> new ArrayList<>()).add(row);
        List<PoolMember> members = new ArrayList<>();
        for (List<Object[]> crew : byCrew.values()) {
            List<BigDecimal> shares = crewShares(crew.size());
            for (int i = 0; i < crew.size(); i++) {
                Object[] row = crew.get(i);
                members.add(new PoolMember(sheetId, (String) row[0], (Long) row[1], null, (String) row[2],
                        shares.get(i), (Boolean) row[3], (Boolean) row[4], null, null, true));
            }
        }
        return members;
    }

    /**
     * A crew's {@code count} equal shares, its lead's first: 100.00 divided by the count, rounded half to even to two
     * decimals, the remainder (100.00 less the shares added up) to the lead, as patrons' shares are split.
     */
    static List<BigDecimal> crewShares(int count) {
        BigDecimal hundred = new BigDecimal("100.00");
        BigDecimal each = hundred.divide(BigDecimal.valueOf(count), 2, RoundingMode.HALF_EVEN);
        List<BigDecimal> shares = new ArrayList<>();
        shares.add(hundred.subtract(each.multiply(BigDecimal.valueOf(count - 1))));
        for (int i = 1; i < count; i++) shares.add(each);
        return shares;
    }

    public boolean isMember(Pool pool, long personId) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM pool_member WHERE pool_id = ? AND person_id = ?",
                Integer.class, pool.id(), personId);
        return n != null && n > 0;
    }

    public void addMember(Pool pool, long personId, BigDecimal share, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO pool_member (pool_id, person_id, share, from_date, to_date, added_on)"
                + " VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                pool.id(), personId, share, sqlDate(from), sqlDate(to), pool.sheetId());
    }

    /** The pool this pool is a member of, or null when it is a member of none. */
    public Pool parentOf(Pool pool) {
        List<Pool> found = jdbc.query("SELECT pl.id, pl.sheet_id, pl.name FROM pool_member m JOIN pool pl ON pl.id = m.pool_id"
                + " WHERE m.member_pool_id = ?",
                (rs, n) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name")), pool.id());
        return found.isEmpty() ? null : found.get(0);
    }

    /** The pools that are members of this pool. */
    public List<Pool> memberPools(Pool pool) {
        return jdbc.query("SELECT mp.id, mp.sheet_id, mp.name FROM pool_member m JOIN pool mp ON mp.id = m.member_pool_id"
                + " WHERE m.pool_id = ?",
                (rs, n) -> new Pool(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name")), pool.id());
    }

    public void addMemberPool(Pool pool, Pool member, BigDecimal share, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO pool_member (pool_id, member_pool_id, share, from_date, to_date, added_on)"
                + " VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                pool.id(), member.id(), share, sqlDate(from), sqlDate(to), pool.sheetId());
    }

    private static Date sqlDate(LocalDate day) {
        return day == null ? null : Date.valueOf(day);
    }

    /**
     * Move a merged person's memberships to the person they were merged into: their share is added to
     * the other's in a pool the other is already in.
     */
    public void mergeMembers(long fromId, long intoId) {
        jdbc.update("UPDATE pool_member m SET share = share + (SELECT f.share FROM pool_member f"
                + " WHERE f.pool_id = m.pool_id AND f.person_id = ?) WHERE m.person_id = ?"
                + " AND EXISTS (SELECT 1 FROM pool_member f WHERE f.pool_id = m.pool_id AND f.person_id = ?)",
                fromId, intoId, fromId);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ? AND pool_id IN"
                + " (SELECT pool_id FROM pool_member WHERE person_id = ?)", fromId, intoId);
        jdbc.update("UPDATE pool_member SET person_id = ? WHERE person_id = ?", intoId, fromId);
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A member of a pool with a share percent: a person (personId set, memberPool null), or another pool
 * (memberPool its name, personId null; name the pool's name). A retired person's share counts as given
 * toward the pool's total, but they get no cut, their share being spread over the members with one. {@code held} is whether a person has a hold in force on the sheet's today: they
 * get no cut, their share being spread over the members with one, though it still counts toward the total.
 * {@code from} and {@code to} are the membership's optional dates; {@code active} is whether they include the
 * sheet's today: a member not active is left out entirely, of the total, the balance and the cuts.
 */
public record PoolMember(String sheetId, String pool, Long personId, String memberPool, String name, BigDecimal share,
        boolean retired, boolean held, LocalDate from, LocalDate to, boolean active) {

    /** Whether the dates, either open, include the day. */
    public static boolean covers(LocalDate from, LocalDate to, LocalDate day) {
        return (from == null || !day.isBefore(from)) && (to == null || !day.isAfter(to));
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';

/** A person in a pool, or another pool (memberPool its name, personId ''), with a share percent (two decimals). A
 *  retired member's share counts toward the total. Their cut is their part of the pool's pot, two decimals
 *  ('' when the pool is unbalanced, there is no pot, or every member is retired); a retired person, or one with a
 *  hold in force on the sheet's today, gets 0.00, their share spread over the members with a cut. A pool that is a member of no pool has the sheet's pot; one
 *  that is a member of another has its cut there as its pot. */
export type PoolMember = {
  personId: string;
  memberPool: string;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
  /** The membership's from- and to-dates ('' for open). */
  from: string;
  to: string;
  /** Whether the dates include the sheet's today: a member not active is left out of the total, the balance and
   *  the cuts (its cut is ''). */
  active: boolean;
};

/** A pool on the sheet: its members in the order added, their total share, and balanced when it is exactly 100.00.
 *  `added` orders the pools as they were added (a larger one added later; a crew's after every pool). `crew` is
 *  whether it is a crew's pool: its lead and members at equal shares (100.00 split as patrons' shares are, the
 *  remainder on the lead), kept by the crew, so no member is added to it here and it is no other pool's member. */
export type Pool = {
  name: string;
  members: PoolMember[];
  totalShare: string;
  balanced: boolean;
  added: number;
  crew: boolean;
};

// Under the people's key: a change to a person (a retirement, a new name) reads the pools again too.
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'] as const;

/** The pools on the sheet, by name. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`)).pools,
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { useUser } from '../session/session';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { sumDue } from '../rates/rates';
import { poolsKey, usePools } from './pools';
import type { Pool } from './pools';

// The sheet's pools: a name entry and an add button, each pool listed below with its total share, whether
// it is balanced (the shares total exactly 100.00; a retired member's counts as given) and its members, each
// with their share and their cut of the pot (blank when the pool is unbalanced, there is no pot or every member is retired, or the member's
// optional from- and to-dates do not include the sheet's today: such a member is left out of the total and balance too). A member is added from the pool's row: a person,
// or another pool (pool:<name>), and a share. A member pool's pot is its cut in the pool above. The server decides
// what is refused — a taken or blank name, a person already in the pool, a share not more than 0.00 and at most
// 100.00 with two decimals, a to-date before the from-date, a pool already in a pool, one containing itself through any chain, or a chain more than
// three deep — and the form shows its error. Each crew is listed as a pool too, under its name (no pool may take a
// crew's name), its members kept by the crew: it has no member form and is offered as no pool's member.
function Pools({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const pools = usePools(sheetId);
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const add = useMutation({
    mutationFn: (body: { name: string }) =>
      postJson<Pool>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, body, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    onError: () => setError('That pool could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once((done) => add.mutate({ name }, { onSettled: done }));
  };

  return (
    <section data-testid="pools">
      <h2>Pools</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input
            data-testid="pool-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {error && (
          <p role="alert" data-testid="pool-form-error">
            {error}
          </p>
        )}
      </form>
      <ul data-testid="pool-list">
        {(pools.data ?? []).map((p) => (
          <PoolRow key={p.name} sheetId={sheetId} pool={p} />
        ))}
      </ul>
    </section>
  );
}

function PoolRow({ sheetId, pool }: { sheetId: string; pool: Pool }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId);
  const pools = usePools(sheetId);
  // A person's id, or pool:<name> for a member pool.
  const [member, setMember] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const add = useMutation({
    mutationFn: (body: { pool: string; personId: string; memberPool: string; share: string; from: string; to: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/pool-members`, body, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    onError: () => setError(`That member could not be added to ${pool.name}.`),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const memberPool = member.startsWith('pool:') ? member.slice('pool:'.length) : '';
    const personId = memberPool ? '' : member;
    once((done) => add.mutate({ pool: pool.name, personId, memberPool, share, from, to }, { onSettled: done }));
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.memberPool ? `pool-${m.memberPool}` : m.personId}
            data-testid={`pool-member-${pool.name}-${m.memberPool ? `pool-${m.memberPool}` : m.personId}`}
          >
            {m.name}
            {m.retired ? ' (retired)' : ''}: <span data-testid="pool-share">{m.share}</span>%, cut{' '}
            <span data-testid="pool-cut">{m.cut}</span>
            {m.from || m.to ? ` (${m.from || 'open'} to ${m.to || 'open'}${m.active ? '' : ', not active'})` : ''}
          </li>
        ))}
      </ul>
      {!pool.crew && (
        <form onSubmit={submit}>
          <select
            data-testid="pool-member-select"
            value={member}
            onChange={(e) => {
              setMember(e.target.value);
              setError('');
            }}
          >
            <option value="">Person…</option>
            {(people.data ?? []).map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
            {(pools.data ?? [])
              .filter((p) => p.name !== pool.name && !p.crew)
              .map((p) => (
                <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
                  {`pool:${p.name}`}
                </option>
              ))}
          </select>{' '}
          <input
            data-testid="pool-member-share"
            placeholder="share %"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              setError('');
            }}
          />{' '}
          <input
            type="date"
            data-testid="pool-member-from"
            aria-label="Member from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              setError('');
            }}
          />{' '}
          <input
            type="date"
            data-testid="pool-member-to"
            aria-label="Member to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              setError('');
            }}
          />{' '}
          <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
            Add member
          </button>
          {error && (
            <p role="alert" data-testid="pool-error">
              {error}
            </p>
          )}
        </form>
      )}
    </li>
  );
}

/** A person's cut total: their cuts in every pool they are a member of, added up (a pool with no cuts adds nothing). */
function cutTotal(pools: Pool[], personId: string): string {
  return sumDue(
    pools.flatMap((p) => p.members.filter((m) => !m.memberPool && m.personId === personId && m.cut !== '').map((m) => m.cut)),
  );
}

function CutHead() {
  return <th>Cut</th>;
}

function PersonCutTotal({ sheetId, person }: { sheetId: string; person: Person }) {
  const pools = usePools(sheetId).data ?? [];
  return <td data-testid="person-cut-total">{cutTotal(pools, person.id)}</td>;
}

// The sheet's cut total: everyone's cut total added up.
function SheetCutTotal({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const pools = usePools(sheetId).data ?? [];
  return (
    <p>
      Cut in all: <strong data-testid="rollup-cut-total">{sumDue(people.map((p) => cutTotal(pools, p.id)))}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: -5.3, Component: Pools }),
  SheetBody.fill({ order: 20.8, Component: SheetCutTotal }),
  PersonHead.fill({ order: 22, Component: CutHead }),
  PersonRow.fill({ order: 22, Component: PersonCutTotal }),
];
